import {FISH} from './fish-config.js';import {fishPayment} from './fish-feed.js';import {fishReceipt} from './fish-stock.js';
/** No instant credit/oxygen grant: only subsequent purchased runtime changes. @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./fish-feed.js').FishTransaction} transact @returns {string|undefined} */
export function upgradeFishAir(state,command,transact){const g=state.fish,p=g?.ponds.find(x=>x.id===command.fishPond);if(!g||!p)return 'fishPondMissing';if(p.efficient)return 'fishUpgradeExists';if(g.stats.saleActions<1)return 'fishSellFirst';if(state.coins<FISH.efficiencyCoins)return 'noCoins';fishPayment(state,'fish.aerator_upgrade',-FISH.efficiencyCoins,'upgrade.'+p.id,transact);p.efficient=true;fishReceipt(g,state.tick,'efficiency',p.id,0,0,FISH.efficiencyCoins);}
